-- New Cloudflare D1 database. No existing customer data is embedded.
CREATE TABLE IF NOT EXISTS submissions (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  name TEXT NOT NULL, email TEXT NOT NULL, phone TEXT NOT NULL,
  interest TEXT NOT NULL, message TEXT, created_at TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS reviews (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  name TEXT NOT NULL, rating INTEGER NOT NULL CHECK(rating BETWEEN 1 AND 5),
  body TEXT NOT NULL, approved INTEGER NOT NULL DEFAULT 0 CHECK(approved IN (0,1)),
  created_at TEXT NOT NULL
);
CREATE INDEX IF NOT EXISTS reviews_public ON reviews(approved,id);
CREATE TABLE IF NOT EXISTS site_content (
  section TEXT PRIMARY KEY, draft TEXT NOT NULL, published TEXT NOT NULL,
  revision INTEGER NOT NULL DEFAULT 0
);
CREATE TABLE IF NOT EXISTS editor_sessions (
  token TEXT PRIMARY KEY, csrf TEXT NOT NULL, expires INTEGER NOT NULL,
  credential TEXT NOT NULL
);
CREATE INDEX IF NOT EXISTS sessions_expiry ON editor_sessions(expires);
CREATE TABLE IF NOT EXISTS rate_limits (
  key TEXT PRIMARY KEY, attempts INTEGER NOT NULL, expires INTEGER NOT NULL
);
CREATE INDEX IF NOT EXISTS rate_expiry ON rate_limits(expires);
