INSERT OR IGNORE INTO site_content(section,draft,published) VALUES('about','{"about_title": "The backbone of every", "about_emphasis": "migrant’s success story.", "vision": "To be the backbone of every migrant’s success story and to offer unparalleled service whilst building dependable relationships with our clients and maintaining confidentiality throughout the process to promote success.", "mission": "At The World Migration, our team of licensed and qualified consultants work closely with clients to bring about the best solutions to all their immigration objectives whilst maintaining confidentiality and other high professional standards. We build strong networks in source countries and our in-depth knowledge of complex and diverse immigration laws that are constantly being updated help achieve optimum results. We invest our energy, experience and knowledge to help create brand new opportunities in the practice of immigration."}','{"about_title": "The backbone of every", "about_emphasis": "migrant’s success story.", "vision": "To be the backbone of every migrant’s success story and to offer unparalleled service whilst building dependable relationships with our clients and maintaining confidentiality throughout the process to promote success.", "mission": "At The World Migration, our team of licensed and qualified consultants work closely with clients to bring about the best solutions to all their immigration objectives whilst maintaining confidentiality and other high professional standards. We build strong networks in source countries and our in-depth knowledge of complex and diverse immigration laws that are constantly being updated help achieve optimum results. We invest our energy, experience and knowledge to help create brand new opportunities in the practice of immigration."}');
INSERT OR IGNORE INTO site_content(section,draft,published) VALUES('welcome','{"welcome_0": "The World Migration is a renowned immigration consultancy with over a decade of expertise in this industry. Our client centric approach and dedicated service will ensure that our clients qualify and get through this process at the first attempt. With a global presence and fail safe operation strategy, we will help your dreams materialize.", "welcome_1": "The entire process of applying for a visa can not only be lengthy and complex but also stressful and expensive. Team up with us and we will simplify the whole process because we genuinely care and that is all it takes to make the difference. We are really excited to work with you!"}','{"welcome_0": "The World Migration is a renowned immigration consultancy with over a decade of expertise in this industry. Our client centric approach and dedicated service will ensure that our clients qualify and get through this process at the first attempt. With a global presence and fail safe operation strategy, we will help your dreams materialize.", "welcome_1": "The entire process of applying for a visa can not only be lengthy and complex but also stressful and expensive. Team up with us and we will simplify the whole process because we genuinely care and that is all it takes to make the difference. We are really excited to work with you!"}');
INSERT OR IGNORE INTO site_content(section,draft,published) VALUES('about_detail_1','{"about_detail_0": "We offer a variety of services including but not limited to, migration consulting services for skilled migrants, procuring work visas, investor visas, entrepreneur visas, study permits, visit visas and document attestation and translations for all countries across the globe. At present we specialize in procuring visas for Australia, Canada, Denmark and Entrepreneur visas for the United Kingdom."}','{"about_detail_0": "We offer a variety of services including but not limited to, migration consulting services for skilled migrants, procuring work visas, investor visas, entrepreneur visas, study permits, visit visas and document attestation and translations for all countries across the globe. At present we specialize in procuring visas for Australia, Canada, Denmark and Entrepreneur visas for the United Kingdom."}');
INSERT OR IGNORE INTO site_content(section,draft,published) VALUES('about_detail_2','{"about_detail_1": "The World Migration is the brain child of a team of experts with extensive and in-house experience in the UK and Canadian Immigration Departments. This consultancy has been set up post the retirement of our team members with the vision of helping people to get their visa application processed smoothly. You can be rest assured that you will fully qualify for the chosen visa of your preference with our impartial advice, offered free of charge even before you become a paying client."}','{"about_detail_1": "The World Migration is the brain child of a team of experts with extensive and in-house experience in the UK and Canadian Immigration Departments. This consultancy has been set up post the retirement of our team members with the vision of helping people to get their visa application processed smoothly. You can be rest assured that you will fully qualify for the chosen visa of your preference with our impartial advice, offered free of charge even before you become a paying client."}');
INSERT OR IGNORE INTO site_content(section,draft,published) VALUES('about_detail_3','{"about_detail_2": "The World Migration is a trusted name in the migration consultancy field with a global presence and we are accredited by the Immigration Consultants of Canada Regulatory Council (ICCRC) and Migration Agents Registration Authority (MARA) in Australia. We truly believe that integrity and honesty should be a key part of the proceedings and the services provided here conform to the highest global standards."}','{"about_detail_2": "The World Migration is a trusted name in the migration consultancy field with a global presence and we are accredited by the Immigration Consultants of Canada Regulatory Council (ICCRC) and Migration Agents Registration Authority (MARA) in Australia. We truly believe that integrity and honesty should be a key part of the proceedings and the services provided here conform to the highest global standards."}');
INSERT OR IGNORE INTO site_content(section,draft,published) VALUES('about_detail_4','{"about_detail_3": "Well, you may rightfully ask, why The World Migration over any other consultancy? We are very proud about the fact that we are extremely honest, reliable and provide service that is 100% value for money. Further, scores of people have benefitted from our “no obligation free visa assessment” that has guided them throughout the complex process with our step by step assistance. Furthermore, we are very pleased to announce that most of our new clients are referral clients and our biggest marketing tool has been word of mouth referral by past clients. For a journey that will be truly special, join hands with The World Migration."}','{"about_detail_3": "Well, you may rightfully ask, why The World Migration over any other consultancy? We are very proud about the fact that we are extremely honest, reliable and provide service that is 100% value for money. Further, scores of people have benefitted from our “no obligation free visa assessment” that has guided them throughout the complex process with our step by step assistance. Furthermore, we are very pleased to announce that most of our new clients are referral clients and our biggest marketing tool has been word of mouth referral by past clients. For a journey that will be truly special, join hands with The World Migration."}');
